export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Idempotency index scoped by (tenant, key). Lookup and insert happen
  // synchronously (no await in between), so concurrent calls cannot both debit.
  private readonly byKey = new Map<string, Receipt>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    const scope = JSON.stringify([tenant, key]);
    const existing = this.byKey.get(scope);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    this.byKey.set(scope, receipt);
    return receipt;
  }
}
EOF
