const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');
async function main() {
  // Transient after commit: retried with same receipt, single debit.
  { const ledger = new Ledger(); const seen = []; let fails = 2;
    const s = new PaymentService(ledger, { acknowledge: async r => { seen.push(r); if (fails-- > 0) throw new Transient('t'); } });
    const r = await s.pay('t1', 'k', 100, 3);
    assert.equal(ledger.entries.length, 1); assert.equal(seen.length, 3);
    assert.ok(seen.every(x => x === r)); }
  // Exhaustion preserves final exception.
  { const ledger = new Ledger(); let n = 0; const errs = [];
    const s = new PaymentService(ledger, { acknowledge: async () => { const e = new Transient('t' + ++n); errs.push(e); throw e; } });
    await assert.rejects(s.pay('t1', 'k', 100, 2), e => e === errs[1]);
    assert.equal(n, 2); assert.equal(ledger.entries.length, 1); }
  // Non-transient not retried.
  { const ledger = new Ledger(); let n = 0; const boom = new Error('boom');
    const s = new PaymentService(ledger, { acknowledge: async () => { n++; throw boom; } });
    await assert.rejects(s.pay('t1', 'k', 100, 5), e => e === boom); assert.equal(n, 1); }
  // Repeat, concurrency, tenant scope, conflict.
  { const ledger = new Ledger();
    const s = new PaymentService(ledger, { acknowledge: async () => {} });
    const [a, b, c] = await Promise.all([s.pay('t1', 'k', 5), s.pay('t1', 'k', 5), s.pay('t1', 'k', 5)]);
    assert.ok(a === b && b === c); assert.equal(ledger.entries.length, 1);
    assert.equal(await s.pay('t1', 'k', 5), a);
    const other = await s.pay('t2', 'k', 5); assert.notEqual(other.id, a.id);
    assert.equal(ledger.entries.length, 2);
    await assert.rejects(s.pay('t1', 'k', 6), /key conflict/);
    await assert.rejects(Promise.all([s.pay('t3', 'k', 1), s.pay('t3', 'k', 2)]), /key conflict/);
    assert.equal(ledger.entries.length, 3); }
  // Validation before any ledger/transport action.
  { const ledger = new Ledger(); let n = 0;
    const s = new PaymentService(ledger, { acknowledge: async () => { n++; } });
    for (const args of [['', 'k', 1], ['t', '', 1], ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', NaN],
        ['t', 'k', 1, 0], ['t', 'k', 1, 6], ['t', 'k', 1, 2.5], ['t', 'k', '1']]) {
      await assert.rejects(s.pay(...args), /invalid payment/);
    }
    assert.equal(ledger.entries.length, 0); assert.equal(n, 0);
    await s.pay('t', 'k', 1, 1); await s.pay('t', 'k2', 1, 5); }
}
module.exports = main();
EOF
